    private List<CenterData.Message> mediaMessages(boolean speech){List<CenterData.Message> out=new ArrayList<>();for(CenterData.Message m:index.selected())if(!m.protectedMedia&&!m.kind.equals("text")&&(!speech||Arrays.asList("video","audio","voice","round").contains(m.kind))&&(mediaKind.isEmpty()||mediaKind.equals(m.kind))&&m.searchable().toLowerCase(Locale.ROOT).contains(mediaSearch.toLowerCase(Locale.ROOT))){try{CenterMedia.check(m);out.add(m);}catch(Exception ignored){}}return out;}
    private void media(boolean speech){
        button("search",()->input("search",mediaSearch,v->{mediaSearch=v;mediaPage=0;show(screen);}));
        button("type",()->choices("type",new String[]{t("all"),"Photo","Video","Audio","Voice","PDF","Document"},i->{mediaKind=new String[]{"","photo","video","audio","voice","pdf","document"}[i];mediaPage=0;show(screen);}));
        button("authors",()->{Map<Long,String> map=new LinkedHashMap<>();for(CenterData.Message m:index.selected())map.put(m.author,m.authorName);List<Long> ids=new ArrayList<>(map.keySet());String[] names=new String[ids.size()+1];names[0]=t("all");for(int i=0;i<ids.size();i++)names[i+1]=map.get(ids.get(i));choices("authors",names,i->{index.scope.authors.clear();if(i>0)index.scope.authors.add(ids.get(i-1));index.saveScope();show(screen);});});
        button("file",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*","image/*","application/pdf","text/*","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.oasis.opendocument.text"});i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,72581);});button("cloud",this::pickCloud);
        if(speech){info(t("offlineSpeech"));button("language",()->input("language",CenterIndex.settings().optString("language","auto"),v->CenterIndex.setting("language",v)));}
        List<CenterData.Message> list=mediaMessages(speech);
        button("selectAll",()->{for(CenterData.Message m:list)pickedMedia.add(m.qualified());show(screen);});
        button("cancel",()->{pickedMedia.clear();show(screen);});
        if(speech)button("transcribe",()->queueMedia(list,"transcribe"));else{button("download",()->queueMedia(list,"download"));button("ocr",()->queueMedia(list,"ocr"));button("describe",()->queueMedia(list,"describe"));button("transcriber",()->show(5));}
        button("queue",this::taskQueue);button("refresh",this::reload);
        info(t("media")+": "+list.size()+" · "+pickedMedia.size());
        int version=uiVersion;
        for(int i=mediaPage*40;i<Math.min(list.size(),(mediaPage+1)*40);i++){
            CenterData.Message m=list.get(i);LinearLayout card=new LinearLayout(getParentActivity());card.setOrientation(LinearLayout.VERTICAL);body.addView(card);
            if(!m.frameTimes.isEmpty()||m.pages>0){android.widget.ImageView preview=new android.widget.ImageView(getParentActivity());preview.setScaleType(android.widget.ImageView.ScaleType.CENTER_CROP);card.addView(preview,new LinearLayout.LayoutParams(-1,dp(160)));CenterThumbnails.load(m,m.frameTimes.isEmpty()?0:m.frameTimes.get(0),m.pages>0?1:0,b->{if(version==uiVersion&&b!=null)preview.setImageBitmap(b);});preview.setOnClickListener(w->mediaDetails(m,0));}
            CheckBox choice=new CheckBox(getParentActivity());choice.setText(m.authorName+" · "+m.sourceTitle+" · "+m.accountName+"\n"+new Date(m.date*1000L)+" · "+m.kind+"\n"+(m.text.length()>160?m.text.substring(0,160)+"…":m.text));choice.setTextColor(getThemedColor(Theme.key_windowBackgroundWhiteBlackText));choice.setChecked(pickedMedia.contains(m.qualified()));choice.setOnCheckedChangeListener((v,on)->{if(on)pickedMedia.add(m.qualified());else pickedMedia.remove(m.qualified());});card.addView(choice);
            TextView details=label(t("details"),14);card.addView(details);details.setOnClickListener(w->mediaDetails(m,0));
            if(!m.transcript.isEmpty())for(CenterTranscript.Segment segment:CenterTranscript.parse(m.transcript)){TextView v=label(CenterTranscript.stamp(segment.start)+" · "+segment.text,14);v.setOnClickListener(w->playAt(m,segment.start));card.addView(v);}
            if(!m.hash.isEmpty()){List<String> copies=new ArrayList<>();try{long hash=Long.parseUnsignedLong(m.hash,16);for(CenterData.Message q:list)if(q!=m&&!q.hash.isEmpty()&&Long.bitCount(hash^Long.parseUnsignedLong(q.hash,16))<=6)copies.add(q.sourceTitle+" · "+q.authorName+" · "+new Date(q.date*1000L));}catch(Exception ignored){}if(!copies.isEmpty()){TextView v=label(t("copies")+"\n"+android.text.TextUtils.join("\n",copies),13);card.addView(v);}}
        }
        if(mediaPage>0)button("previous",()->{mediaPage--;show(screen);});if((mediaPage+1)*40<list.size())button("next",()->{mediaPage++;show(screen);});
    }
    private void queueMedia(List<CenterData.Message> list,String op){List<CenterData.Message> selected=new ArrayList<>();long bytes=0,duration=0;for(CenterData.Message m:list)if(pickedMedia.contains(m.qualified())){selected.add(m);bytes+=m.bytes;duration+=m.duration;}
        if(selected.isEmpty()){toast(t("selected"));return;}long totalBytes=bytes,totalDuration=duration;
        Runnable launch=()->new AlertDialog.Builder(getParentActivity()).setTitle(t("estimate")).setMessage(t("media")+": "+selected.size()+"\n"+t("downloadEstimate")+": "+totalBytes+" / "+(totalDuration/60000)).setPositiveButton(t("continue"),(d,w)->{
            for(CenterData.Message m:selected){String action=op;if(op.equals("ocr")&&(m.kind.equals("video")||m.kind.equals("round")))action="frames";if((op.equals("ocr")||op.equals("download"))&&(m.kind.equals("pdf")||m.kind.equals("document")))action="document";if(op.equals("download")&&(m.kind.equals("video")||m.kind.equals("round")))action="frames";CenterTaskService.enqueue(Collections.singletonList(m),action);}toast(t("queue"));
        }).setNegativeButton(t("cancel"),null).show();
        if(op.equals("describe")&&!CenterIndex.settings().optBoolean("consent",false))new AlertDialog.Builder(getParentActivity()).setMessage(t("consent")).setPositiveButton(t("confirm"),(d,w)->{CenterIndex.setting("consent",true);launch.run();}).setNegativeButton(t("cancel"),null).show();else launch.run();
    }
    private void taskQueue(){int version=++uiVersion;body.removeAllViews();heading("queue");CenterStore.IO.execute(()->{List<JSONObject> jobs=new ArrayList<>();try{for(int a=0;a<UserConfig.MAX_ACCOUNT_COUNT;a++)if(UserConfig.getInstance(a).isClientActivated())jobs.addAll(CenterStore.get().list(a,UserConfig.getInstance(a).getClientUserId(),"job"));}catch(Exception e){FileLog.e(e);}AndroidUtilities.runOnUIThread(()->{if(!unlocked||!foreground||version!=uiVersion)return;for(JSONObject job:jobs){JSONObject m=job.optJSONObject("message");info((m==null?"":m.optString("sourceTitle"))+" · "+t(job.optString("state"))+" · "+job.optInt("percent")+"%\n"+job.optString("error"));button("pause",()->CenterTaskService.change(job,"paused"));button("resume",()->{CenterTaskService.change(job,"queued");CenterTaskService.startManual();});button("delete",()->CenterTaskService.change(job,"cancelled"));}button("refresh",this::taskQueue);uiHandler.postDelayed(()->{if(unlocked&&foreground&&version==uiVersion)taskQueue();},3000);});});}
