        if(m.pages>1){TextView next=label(t("page")+" "+Math.max(1,page)+" / "+m.pages+" · "+t("next"),14);next.setOnClickListener(w->{dialog.dismiss();mediaDetails(m,Math.max(1,page)%m.pages+1);});content.addView(next);}
